import { useEffect, useRef } from 'react';

import { CLARA_CONTEXT_CHANGE_TOAST_MESSAGE } from 'components/ai/constants';
import { toast } from 'components/ai/utils/toastStore';

interface UseClaraProjectKeySyncOptions {
  projectKey: string;
  stateKey: string;
  isOpen: boolean;
  showClaraDomainDropdown: boolean;
  conversationId: string | null;
  messagesCount: number;
  onProjectKeyChange: () => void;
}

export function useClaraProjectKeySync({
  projectKey,
  stateKey,
  isOpen,
  showClaraDomainDropdown,
  conversationId,
  messagesCount,
  onProjectKeyChange,
}: UseClaraProjectKeySyncOptions) {
  const previousProjectKeyRef = useRef(projectKey);
  const previousStateKeyRef = useRef(stateKey);
  const pendingContextChangeToastRef = useRef(false);

  useEffect(() => {
    const projectKeyChanged = previousProjectKeyRef.current !== projectKey;
    const stateKeyChanged = previousStateKeyRef.current !== stateKey;
    const hadActiveConversation = Boolean(conversationId) || messagesCount > 0;
    const shouldNotifyContextChange =
      showClaraDomainDropdown &&
      stateKeyChanged &&
      projectKeyChanged &&
      hadActiveConversation;

    if (projectKeyChanged) {
      previousProjectKeyRef.current = projectKey;
      onProjectKeyChange();
    }

    if (stateKeyChanged) {
      previousStateKeyRef.current = stateKey;
    }

    if (shouldNotifyContextChange) {
      pendingContextChangeToastRef.current = true;
    }

    if (
      isOpen &&
      showClaraDomainDropdown &&
      pendingContextChangeToastRef.current
    ) {
      pendingContextChangeToastRef.current = false;
      toast({
        type: 'success',
        message: CLARA_CONTEXT_CHANGE_TOAST_MESSAGE,
      });
    }
  }, [
    conversationId,
    isOpen,
    messagesCount,
    onProjectKeyChange,
    projectKey,
    showClaraDomainDropdown,
    stateKey,
  ]);
}
